<?php require_once '../config.php'; requireLogin(); header('Content-Type: application/json; charset=utf-8');try{$uid=getUserId();$t=getAccessToken();if($_SERVER['REQUEST_METHOD']==='POST'){$limit=max(1,min(200,(int)($_POST['daily_limit']??20)));sb_upsert('user_settings',['user_id'=>$uid,'setting_key'=>'daily_limit','setting_value'=>(string)$limit],['user_id','setting_key'],$t);sb_upsert('user_settings',['user_id'=>$uid,'setting_key'=>'pronunciation','setting_value'=>isset($_POST['pronunciation'])?'1':'0'],['user_id','setting_key'],$t);echo json_encode(['success'=>true],JSON_UNESCAPED_UNICODE);exit;}$rows=sb_query('user_settings',['select'=>'setting_key,setting_value','user_id'=>'eq.'.$uid,'limit'=>30],$t);$out=['daily_limit'=>'20','pronunciation'=>'1'];foreach($rows as $r)$out[$r['setting_key']]=$r['setting_value'];echo json_encode(['success'=>true]+$out,JSON_UNESCAPED_UNICODE);}catch(Throwable $e){http_response_code(400);echo json_encode(['success'=>false,'error'=>sb_error_message($e)],JSON_UNESCAPED_UNICODE);}